def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_count = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 80:
                    aggressive_count += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    units = supply / float(WATER_REQ)

    if prev_bids:
        top_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        top_prev = 0.0
        avg_prev = 0.0

    if hp <= 2 or no_water >= 2:
        urgent = max(62.0, top_prev + 2.0)
        return float(min(budget, urgent))

    if hp <= 4 or no_water >= 1:
        if units >= 1.7:
            bid = max(26.0, min(44.0, avg_prev * 0.45 + 6.0))
        else:
            bid = max(38.0, min(58.0, top_prev * 0.6 + 8.0))
        return float(min(budget, bid))

    if units >= 1.8:
        bid = 16.0
    elif units >= 1.5:
        bid = 22.0
    elif units >= 1.25:
        bid = 29.0
    else:
        bid = 36.0

    if top_prev > 0:
        if top_prev >= 100:
            bid -= 4.0
        elif top_prev >= 70:
            bid += 2.0
        elif top_prev <= 25:
            bid += 3.0

    if aggressive_count >= 2 and hp >= 6 and no_water == 0:
        bid -= 3.0

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.55 + 6.0)

    bid = max(8.0, bid)
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    num_slots = int(current_supply / WATER_REQ)

    if num_slots == 0:
        if my_hp <= 2:
            return min(my_budget, DAILY_SALARY * 0.95)
        return min(my_budget, DAILY_SALARY * 0.1)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    current_bid = DAILY_SALARY * 0.6

    if my_hp <= 2:
        current_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        current_bid = max(current_bid, DAILY_SALARY * 0.8)
    elif my_no_water_days > 0:
        current_bid = max(current_bid, DAILY_SALARY * 0.75)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        current_bid = max(current_bid, DAILY_SALARY * 0.9)
    elif remaining_days <= 4:
        current_bid = max(current_bid, DAILY_SALARY * 0.7)

    highest_prev_bid = 0.0
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev_trace['bid'])

    if highest_prev_bid > 0:
        if my_hp <= 4 or my_no_water_days > 0:
            current_bid = max(current_bid, highest_prev_bid + 5.0)
        else:
            current_bid = max(current_bid, highest_prev_bid + 1.0)

    final_bid = min(my_budget, current_bid)

    if (my_hp <= 4 or my_no_water_days > 0) and final_bid < DAILY_SALARY * 0.4:
        final_bid = min(my_budget, DAILY_SALARY * 0.4)

    return max(0.0, final_bid)

